/**
 * Scanner.
 *
 * Every number on this page came from src/engine/ at BUILD time and was written
 * to src/data/generated/engine-snapshot.js. Nothing is computed here: the
 * scanner owns no calculation, and neither does its screen. A value recomputed
 * in the browser would eventually disagree with the one the backtester traded
 * on, and the whole point is that they cannot.
 *
 * COVERAGE IS PART OF THE ANSWER. "6 matches" is only meaningful next to "out
 * of 14 evaluated, 0 that could not be looked at". Both are rendered, always.
 */

const DASH = "—"
const isNum = v => typeof v === "number" && Number.isFinite(v)

const num = (v, d = 2) => (isNum(v) ? v.toFixed(d) : DASH)
const usd = (v, d = 2) => (isNum(v) ? (v < 0 ? "−$" : "$") + Math.abs(v).toFixed(d) : DASH)
const pct = (v, d = 1) => (isNum(v) ? (v > 0 ? "+" : "") + v.toFixed(d) + "%" : DASH)

function compactMoney(v) {
  if (!isNum(v)) return DASH
  const abs = Math.abs(v)
  if (abs >= 1e9) return "$" + (abs / 1e9).toFixed(1) + "B"
  if (abs >= 1e6) return "$" + (abs / 1e6).toFixed(0) + "M"
  if (abs >= 1e3) return "$" + (abs / 1e3).toFixed(0) + "K"
  return "$" + abs.toFixed(0)
}

/** RSI bands, named the way a trader reads them. */
function rsiTone(value) {
  if (!isNum(value)) return "neutral"
  if (value >= 70) return "reduce"
  if (value <= 30) return "buy"
  return "neutral"
}

