/**
 * Distance from VWAP, with the side it is on carried by colour.
 *
 * Above VWAP is the side institutional buyers are winning on, below is the
 * side sellers are — so this reads as a direction, not just a magnitude. The
 * sign is always printed, because "0.4%" without it is ambiguous exactly when
 * it matters most.
 */
function VwapDistance({ value }) {
  if (!isNum(value)) {
    return <span className="muted" title="No VWAP: the window has no traded volume yet">{DASH}</span>
  }
  const tone = value > 0 ? "up" : value < 0 ? "down" : "flat"
  return (
    <span
      className={"vwap-dist vwap-dist--" + tone}
      title={value > 0 ? "Trading above VWAP" : value < 0 ? "Trading below VWAP" : "At VWAP"}
    >
      {value > 0 ? "+" : ""}
      {value.toFixed(2)}%
    </span>
  )
}

function TrendPips({ score }) {
  if (!isNum(score)) return <span className="muted">{DASH}</span>
  const tone = score > 0 ? "up" : score < 0 ? "down" : "flat"
  return (
    <span className={"trend-pips trend-pips--" + tone} title={`EMA stack score ${score} of ±3`}>
      {[1, 2, 3].map(i => (
        <i key={i} className={"trend-pips__pip" + (Math.abs(score) >= i ? " is-on" : "")} />
      ))}
      <span className="trend-pips__value">{score > 0 ? "+" + score : score}</span>
    </span>
  )
}

export default function ScannerPage({ location }) {
  const { toast, show: showToast, dismiss: dismissToast } = useToast()
  const [activeId, setActiveId] = useState(scans[0]?.id ?? null)
  const [selected, setSelected] = useState(null)

  const scan = useMemo(() => scans.find(s => s.id === activeId) ?? scans[0], [activeId])
  const detail = useMemo(
    () => (selected ? scan.rows.find(r => r.symbol === selected) ?? null : null),
    [scan, selected]
  )

  const signalCount = scan.rows.reduce((a, r) => a + r.signals.length, 0)

  return (
    <Shell location={location}>
      <div className="page">
        <header className="page__head">
          <div className="page__heading">
            <Breadcrumb items={[{ label: "MarketScan", to: "/" }, { label: "Scanner" }]} />
            <h1 className="page__title">Scanner</h1>
            <p className="page__lede">
              Four screens over {universe.tradable.length} symbols, filtered on the same feature
              vectors the backtester trades. Every exclusion is named.
            </p>
          </div>
          <div className="page__meta">
            <span className="page__meta-item">
              <span className="page__meta-label">Data</span>
              <DataStatus source={source} onLocked={() => showToast(source.lockNote)} />
            </span>
            <span className="page__meta-item">
              <span className="page__meta-label">Window</span>
              <span className="page__meta-value">
                {barCount} {timeframe} bars
              </span>
            </span>
            <span className="page__meta-item">
              <span className="page__meta-label">Built</span>
              <span className="page__meta-value">{generatedAt.slice(0, 10)}</span>
            </span>
          </div>
        </header>

        <div className="scan-tabs" role="tablist">
          {scans.map(s => (
            <button
              key={s.id}
              type="button"
              role="tab"
              aria-selected={s.id === scan.id}
              className={"scan-tabs__tab" + (s.id === scan.id ? " is-active" : "")}
              onClick={() => {
                setActiveId(s.id)
                setSelected(null)
              }}
            >
              <span className="scan-tabs__name">{s.name}</span>
              <span className="scan-tabs__count">{s.matched}</span>
            </button>
          ))}
        </div>

        <Panel
          title={scan.name}
          subtitle={scan.description}
          flush
          actions={
            <span className="panel__stat">
              <strong>{scan.matched}</strong> of {scan.evaluated} evaluated
            </span>
          }
        >
          <div className="scan-criteria">
            {scan.appliedFilters.map(f => (
              <span className="scan-criteria__chip" key={f.key}>
                <span className="scan-criteria__label">{f.label}</span>
                <span className="scan-criteria__value">{f.summary}</span>
              </span>
            ))}
          </div>

          <DataTable
            columns={COLUMNS}
            rows={scan.rows}
            rowKey={row => row.symbol}
            initialSort={{ key: "score", direction: "desc" }}
            onRowClick={row => setSelected(row.symbol === selected ? null : row.symbol)}
            minWidth={1180}
            emptyMessage={
              `Nothing matched. ${scan.evaluated} symbols were evaluated in full — this is a ` +
              `result, not a gap in the data.`
            }
          />
        </Panel>

        <CoverageNote
          evaluated={scan.evaluated}
          universe={scan.universe}
          matched={scan.matched}
          rejected={scan.rejected}
          excluded={scan.excluded}
        />

        {detail && <ScoreDetail row={detail} />}

        <Panel
          title="Live signals"
          subtitle={
            signals.length
              ? `${signals.length} strategy ${signals.length === 1 ? "entry" : "entries"} on the most recent bar, across the whole universe.`
              : "No strategy fired on the most recent bar. That is an ordinary outcome and not a data problem."
          }
        >
          {signals.length ? (
            <ul className="signal-list">
              {signals.map(signal => (
                <li className="signal-list__item" key={signal.id}>
                  <TickerMark symbol={signal.symbol} size={32} />
                  <div className="signal-list__body">
                    <div className="signal-list__head">
                      <span className="signal-list__symbol">{signal.symbol}</span>
                      <span className="signal-list__strategy">{signal.strategyName}</span>
                      <Badge tone={signal.direction === "long" ? "buy" : "sell"}>{signal.direction}</Badge>
                    </div>
                    <p className="signal-list__trigger">{signal.trigger}</p>
                    <p className="signal-list__meta">
                      {signal.timeISO.slice(0, 10)} · close {usd(signal.price)} ·{" "}
                      {Math.round(signal.coverage * 100)}% measured inputs
                    </p>
                  </div>
                  <ScoreBar score={signal.score} coverage={signal.coverage} size="lg" />
                </li>
              ))}
            </ul>
          ) : (
            <p className="empty-note">
              Strategies are evaluated on every bar; this one produced nothing. The scan above
              still lists what matched the screen — a screen and a strategy entry are different
              questions.
            </p>
          )}
        </Panel>
      </div>
      <Toast toast={toast} onDismiss={dismissToast} />
    </Shell>
  )
}

/** The score, decomposed. A composite nobody can take apart is a number to distrust. */
function ScoreDetail({ row }) {
  const components = row.scoreComponents || []
  return (
    <Panel
      title={`${row.symbol} — how the score was built`}
      subtitle={
        `Eight weighted components. An input that could not be measured is shown as ` +
        `unavailable and scored neutral, never as zero.`
      }
    >
      <table className="score-table">
        <thead>
          <tr>
            <th>Component</th>
            <th className="num">Weight</th>
            <th className="num">Value</th>
            <th className="num">Normalised</th>
            <th>Contribution</th>
          </tr>
        </thead>
        <tbody>
          {components.map(c => (
            <tr key={c.key} className={c.available ? "" : "is-unavailable"}>
              <td>
                <span className="score-table__label">{c.label}</span>
                <span className="score-table__bounds">{c.bounds}</span>
              </td>
              <td className="num">{(c.weight * 100).toFixed(0)}%</td>
              <td className="num">{c.available ? num(c.raw, 2) : <span className="muted">unavailable</span>}</td>
              <td className="num">{num(c.normalised, 2)}</td>
              <td>
                <span className="score-table__bar">
                  <span
                    className="score-table__fill"
                    style={{ width: `${Math.max(0, Math.min(100, (c.contribution / (c.weight * 100)) * 100))}%` }}
                  />
                </span>
              </td>
            </tr>
          ))}
        </tbody>
        <tfoot>
          <tr>
            <td colSpan={4}>Composite</td>
            <td className="num score-table__total">{num(row.score, 2)}</td>
          </tr>
        </tfoot>
      </table>
    </Panel>
  )
}

export const Head = () => <title>Scanner · MarketScan</title>
