import React, { useState } from "react"

/**
 * What the screen could NOT look at, and what it looked at and rejected.
 *
 * "6 matches" is not an answer on its own. Six out of fourteen evaluated is one
 * claim; six out of nine, with five symbols never examined, is a different and
 * much weaker one. A scanner that reports only the numerator is reporting a
 * number that cannot be checked.
 *
 * Two categories, deliberately kept apart:
 *   REJECTED — never evaluated. No bars, or not enough history for the
 *              indicators to exist. Not a miss; it was not looked at.
 *   EXCLUDED — evaluated in full and failed a named filter, with the value that
 *              failed it.
 */

export default function CoverageNote({ evaluated, universe, matched, rejected = [], excluded = [] }) {
  const [open, setOpen] = useState(false)
  const clean = rejected.length === 0

  return (
    <section className="coverage">
      <div className="coverage__summary">
        <span className="coverage__headline">
          <strong>{matched}</strong> matched
        </span>
        <span className="coverage__sep">·</span>
        <span>
          <strong>{evaluated}</strong> of {universe} symbols evaluated
        </span>
        {!clean && (
          <>
            <span className="coverage__sep">·</span>
            <span className="coverage__warn">
              <strong>{rejected.length}</strong> could not be looked at
            </span>
          </>
        )}
        <button type="button" className="coverage__toggle" onClick={() => setOpen(v => !v)}>
          {open ? "Hide detail" : "Why?"}
        </button>
      </div>

      {open && (
        <div className="coverage__detail">
          {rejected.length > 0 && (
            <div className="coverage__group">
              <h3 className="coverage__group-title">Never evaluated ({rejected.length})</h3>
              <p className="coverage__group-note">
                These were not screened at all. Their absence from the results says nothing about
                them.
              </p>
              <ul className="coverage__list">
                {rejected.map(r => (
                  <li key={r.symbol}>
                    <span className="coverage__symbol">{r.symbol}</span>
                    <span className="coverage__code">{r.code}</span>
                    <span className="coverage__reason">{r.reason}</span>
                  </li>
                ))}
              </ul>
            </div>
          )}

          {excluded.length > 0 && (
            <div className="coverage__group">
              <h3 className="coverage__group-title">Evaluated and excluded ({excluded.length})</h3>
              <p className="coverage__group-note">
                Screened in full against every filter. The first failure is shown; a symbol that
                missed several is listed with all of them, because "why isn't X here?" usually has
                more than one answer.
              </p>
              <ul className="coverage__list">
                {excluded.map(e => (
                  <li key={e.symbol}>
                    <span className="coverage__symbol">{e.symbol}</span>
                    <span className="coverage__code">{e.code}</span>
                    <span className="coverage__reason">
                      {e.reason}
                      {e.failed && e.failed.length > 1 && (
                        <span className="coverage__also"> +{e.failed.length - 1} more</span>
                      )}
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          )}

          {clean && excluded.length === 0 && (
            <p className="coverage__group-note">
              Every symbol in the universe was evaluated and every one matched.
            </p>
          )}
        </div>
      )}
    </section>
  )
}
