import React from "react"

/**
 * Signal pill. `tone` may be passed explicitly, otherwise it is inferred from
 * the label — so <Badge value="Strong buy" /> gets the green treatment without
 * the caller repeating itself.
 */

const TONE_BY_LABEL = {
  "strong buy": "strong-buy",
  buy: "buy",
  bullish: "bullish",
  neutral: "neutral",
  hold: "neutral",
  reduce: "reduce",
  sell: "sell",
  bearish: "bearish",
  new: "new",
}

export default function Badge({ value, tone, children, className }) {
  const label = children ?? value
  const inferred =
    tone || TONE_BY_LABEL[String(label ?? "").trim().toLowerCase()] || "neutral"
  const classes = ["badge", "badge--" + inferred, className].filter(Boolean).join(" ")

  return <span className={classes}>{label}</span>
}
