import React from "react"

/**
 * The padlock that sits over a control gated behind a paid plan.
 *
 * It is rendered as a sibling overlay rather than inside the control's label,
 * so a disabled button still shows it and a screen reader still reaches it.
 * `onActivate` fires on click and on Enter/Space — a lock that only responds
 * to a mouse leaves keyboard users with a dead control and no explanation.
 *
 * The badge says "locked". The TOAST says why. Keeping those apart means the
 * icon can sit in a dense tab strip without a sentence of copy beside it.
 */
export default function LockBadge({ onActivate = () => {}, label = "Locked" }) {
  function activate(event) {
    event.preventDefault()
    event.stopPropagation()
    onActivate()
  }

  return (
    <span
      className="lock-badge"
      role="button"
      tabIndex={0}
      aria-label={`${label} — requires a paid Massive subscription`}
      onClick={activate}
      onKeyDown={event => {
        if (event.key === "Enter" || event.key === " ") activate(event)
      }}
    >
      <svg viewBox="0 0 24 24" width="11" height="11" aria-hidden="true" focusable="false">
        <path
          d="M17 9V7a5 5 0 0 0-10 0v2H6a1 1 0 0 0-1 1v9a1 1 0 0 0 1 1h12a1 1 0 0 0 1-1v-9a1 1 0 0 0-1-1h-1ZM9 7a3 3 0 0 1 6 0v2H9V7Z"
          fill="currentColor"
        />
      </svg>
    </span>
  )
}
