import React from "react"

/**
 * The composite score, with its own coverage attached.
 *
 * A 0-100 number printed alone invites a precision it does not have. This one
 * was built from eight components, and some of them may not have been
 * measurable — an early-listing symbol has no 52-week range, a thin one has no
 * usable relative volume. Those are scored NEUTRAL, not zero, and the bar says
 * how much of the score rested on real measurement.
 *
 * The coverage marker is drawn as a notch rather than a second number, because
 * two numbers side by side read as a comparison and this is a caveat.
 */

const isNum = v => typeof v === "number" && Number.isFinite(v)

function band(score) {
  if (!isNum(score)) return "none"
  if (score >= 70) return "high"
  if (score >= 55) return "mid"
  if (score >= 40) return "low"
  return "weak"
}

export default function ScoreBar({ score, coverage = 1, size = "md" }) {
  if (!isNum(score)) {
    return <span className="score-bar score-bar--none" title="Not scoreable from the available inputs">—</span>
  }

  const tone = band(score)
  const measured = isNum(coverage) ? Math.max(0, Math.min(1, coverage)) : 1
  const partial = measured < 0.999

  const title = partial
    ? `Score ${score.toFixed(2)} — ${Math.round(measured * 100)}% of the weight came from measured inputs; the rest scored neutral`
    : `Score ${score.toFixed(2)} from fully measured inputs`

  return (
    <span className={`score-bar score-bar--${tone} score-bar--${size}`} title={title}>
      <span className="score-bar__value">{score.toFixed(1)}</span>
      <span className="score-bar__track">
        <span className="score-bar__fill" style={{ width: `${Math.max(2, Math.min(100, score))}%` }} />
        {partial && (
          <span
            className="score-bar__coverage"
            style={{ left: `${Math.max(0, Math.min(100, measured * 100))}%` }}
            aria-hidden="true"
          />
        )}
      </span>
      {partial && <span className="score-bar__caveat">{Math.round(measured * 100)}%</span>}
    </span>
  )
}
